 const header=section(null,'india-chart-header'),instrument=document.createElement('h3');instrument.id='fcInstrumentTitle';instrument.textContent=symbol;header.append(instrument);const toolbar=section(null,'market-controls india-chart-toolbar');toolbar.append(field('fcResolution'),field('fcProvider'),node('fcLoad'),node('fcPlan'));header.append(toolbar);
