 const links=section(null,'india-chart-links');links.append(node('fcTv'));const info=document.createElement('details');info.className='india-options';const summary=document.createElement('summary');summary.textContent='Chart data, limits & other links';const brokerNote=node('fcBrokerPanel').querySelector('.small-note'),fyersLink=host.querySelector('a[href="https://trade.fyers.in"]');info.append(summary,node('fcTvNote'),brokerNote,node('fcReloadTV'),fyersLink);
