 const $=id=>host.querySelector('#'+id);let chart=null,bars=[],active=true,version=0,searchVersion=0,loadId=0,busy=false,tvKey=null,tvCleanup=null,lastQuote=null,loadController=null,tvDeadline=null,drawingCleanup=null,readoutCleanup=null,fullscreen=false,previousOverflow=null;
