 function provider(){const broker=$('fcProvider').value==='fyers';$('fcTvPanel').hidden=broker;$('fcBrokerPanel').hidden=!broker;for(const id of ['fcType','fcEma','fcFit','fcZoomIn','fcZoomOut','fcScale','fcFullscreen'])$(id).disabled=!broker;if(broker){try{draw()}catch(e){$('fcChart').textContent=e.message;status(e.message,true)}}else renderTV()}
