 function change(){loadController?.abort();version++;loadId++;busy=false;$('fcLoad').disabled=false;bars=[];lastQuote=null;clear();clearTV();$('fcTradingView').textContent='Load the selected instrument to update TradingView.';$('fcQuote').textContent='Selection changed. Load the chart to fetch FYERS data.';link();status('Load the selected instrument and timeframe.');onSymbol(sourceSymbol())}
 $('fcSymbol').oninput=change;$('fcResolution').onchange=()=>{change();resolveAndLoad()};const resolveAndLoad=async()=>{const raw=sourceSymbol(),token=version;if(!/-(?:EQ|BE|BZ|SM|ST|INDEX)$/.test(raw)&&!/\d.*(?:FUT|CE|PE)$/.test(raw)){try{const d=await api('/api/fyers/resolve?symbol='+encodeURIComponent(raw));if(!active||token!==version||sourceSymbol()!==raw)return;if(typeof d.symbol!=='string'||!/^(NSE|BSE|MCX):[A-Z0-9&._-]{2,65}$/.test(d.symbol))throw Error('Instrument lookup returned no valid symbol.');$('fcSymbol').value=d.symbol;change()}catch(e){if(active&&token===version)status(e.message,true);return}}return load()};$('fcLoad').onclick=resolveAndLoad;$('fcSymbol').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();resolveAndLoad()}};$('fcType').onchange=draw;$('fcEma').onchange=draw;$('fcScale').onchange=draw;$('fcFit').onclick=()=>chart?.timeScale().fitContent();for(const [id,factor]of [['fcZoomIn',.7],['fcZoomOut',1.4]])$(id).onclick=()=>{const t=chart?.timeScale(),r=t?.getVisibleLogicalRange();if(r){const middle=(r.from+r.to)/2,half=(r.to-r.from)*factor/2;t.setVisibleLogicalRange({from:middle-half,to:middle+half})}};
