 $('fcFind').onclick=async()=>{const token=++searchVersion,segment=$('fcSegment').value,search=$('fcSearch').value.trim();$('fcFind').disabled=true;$('fcResults').innerHTML='<option value="">Searching…</option>';try{const d=await api('/api/fyers/instruments?segment='+segment+'&search='+encodeURIComponent(search));if(!active||token!==searchVersion)return;if(!Array.isArray(d.instruments)||d.instruments.some(r=>!r||typeof r.symbol!=='string'||typeof r.name!=='string'))throw Error('FYERS instrument response invalid.');$('fcResults').innerHTML='<option value="">Choose an instrument</option>'+d.instruments.map(r=>'<option value="'+esc(r.symbol)+'">'+esc(r.symbol+' · '+r.name)+'</option>').join('');$('fcSearchStatus').textContent=d.total+' matches · showing first '+d.instruments.length+' · directory fetched '+stamp(d.asOf)}catch(e){if(active&&token===searchVersion){$('fcSearchStatus').textContent=e.message;$('fcResults').innerHTML='<option value="">Search again</option>'}}finally{if(active&&token===searchVersion)$('fcFind').disabled=false}};
 $('fcSearch').oninput=()=>{searchVersion++;$('fcFind').disabled=false;$('fcResults').innerHTML='<option value="">Search the updated query</option>'};$('fcSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('fcFind').click()}};$('fcProvider').onchange=provider;$('fcReloadTV').onclick=()=>{clearTV();$('fcProvider').value='tv';provider()};
