 $('fcFullscreen').onclick=()=>toggleFullscreen();const exitFullscreen=e=>{if(e.key==='Escape'&&fullscreen)toggleFullscreen(false)};document.addEventListener('keydown',exitFullscreen);
 const timer=setInterval(()=>{if(active&&!document.hidden&&$('fcProvider').value==='fyers'&&$('fcAuto').checked)resolveAndLoad()},30000);const freshness=setInterval(()=>{if(active&&!document.hidden)quoteText()},1000);$('fcProvider').value='fyers';link();provider();resolveAndLoad();return ()=>{toggleFullscreen(false);document.removeEventListener('keydown',exitFullscreen);loadController?.abort();active=false;version++;searchVersion++;clearInterval(timer);clearInterval(freshness);clear();clearTV()};
